 const oldAliases=JSON.parse(git('show',r.baselineSourceCommit+':data/klink-progress-image-aliases-20261030.json')),aliases=json('data/klink-progress-image-aliases-20261030.json');assert.deepEqual(aliases,{...oldAliases,...Object.fromEntries(m.rows.map(x=>[x.row.url,oldAliases[x.oldRow.url]??x.oldRow.url]))});
